{
  "name": "PyOpticon 仪表板套接字客户端",
  "name_en": "PyOpticon Dashboard Socket Client",
  "manufacturer": "",
  "description": "用于通过套接字与 PyOpticon 仪表板通信的非物理软件组件。它供独立的 Python 脚本远程读取或设置界面部件字段、触发确认操作、在仪表板上下文中求值或执行代码，并关闭连接，常用于实验界面自动化与远程控制。",
  "description_en": "A non-physical software component for communicating with a PyOpticon dashboard over a socket. It allows separate Python scripts to remotely read or set widget fields, trigger confirm actions, evaluate expressions or execute functions in the dashboard context, and close the connection, for experiment UI automation and remote control.",
  "actions": [
    {
      "action_name": "auto-set_field",
      "description": "设置部件字段值",
      "description_en": "set widget field value"
    },
    {
      "action_name": "auto-do_confirm",
      "description": "触发部件确认操作",
      "description_en": "trigger a widget confirm action"
    },
    {
      "action_name": "auto-do_eval",
      "description": "在仪表板上下文中求值表达式",
      "description_en": "evaluate an expression in the dashboard context"
    },
    {
      "action_name": "auto-do_exec",
      "description": "在仪表板上下文中执行函数",
      "description_en": "execute a function in the dashboard context"
    },
    {
      "action_name": "auto-close",
      "description": "关闭套接字连接",
      "description_en": "close the socket connection"
    },
    {
      "action_name": "auto-get_field",
      "description": "获取部件字段值",
      "description_en": "get widget field value"
    }
  ],
  "tag_hints": [
    "PyOpticon dashboard",
    "socket communication",
    "experiment UI automation",
    "remote widget control",
    "Python scripting",
    "dashboard field access"
  ]
}

